(() => {
  const {$,esc,read,write,toast,tile,image}=Atlas,model=AtlasDeck;
  const data=window.ATLAS_CATALOG,all=data.cards,lookup=new Map(),unique=new Map();
  all.forEach(c=>{lookup.set(c.uid,c);if(!unique.has(c.id)||c.uid===c.id)unique.set(c.id,c);});unique.forEach((c,id)=>lookup.set(id,c));
  const blank=()=>({name:'Minha tripulação',leader:null,format:'study',donCount:10,donArt:null,cards:{}});
  let deck=blank(),step=1,page=1,leaderLimit=48,hand=null,savedId=null,pending=null;
  const savedRaw=read('atlas-deck-draft',null);if(savedRaw){try{deck=model.parseImport(model.exported(savedRaw),lookup);step=2;}catch{}}
  const params=new URLSearchParams(location.search);if(params.has('leader')){const c=lookup.get(params.get('leader'));if(c?.type==='LEADER'){deck.leader=c.uid;step=1;}}if(params.has('add'))pending=lookup.get(params.get('add'));if(params.has('don')){const c=lookup.get(params.get('don'));if(c?.type==='DON')deck.donArt=c.uid;}
  const leaders=[...unique.values()].filter(c=>c.type==='LEADER');const main=[...unique.values()].filter(c=>['CHARACTER','EVENT','STAGE'].includes(c.type));const dons=[...unique.values()].filter(c=>c.type==='DON');
  function message(text,error=false){$('#builder-feedback').textContent=text;$('#builder-feedback').classList.toggle('is-error',error);}
  const savedList=()=>{const rows=read('atlas-saved-decks',[]);return Array.isArray(rows)?rows.filter(r=>r&&typeof r.id==='string'&&r.data):[];};
  function saveDraft(){if(!write('atlas-deck-draft',deck))message('O navegador não permitiu salvar o rascunho.',true);}
  function fillSaved(){const list=savedList();$('#saved-decks').innerHTML='<option value="">Escolha um deck salvo</option>'+list.map(row=>`<option value="${esc(row.id)}">${esc(row.data.name)} · ${row.data.cards.reduce((n,r)=>n+r.quantity,0)}/50</option>`).join('');if(savedId)$('#saved-decks').value=savedId;}
  function setStep(next){if(next>1&&!deck.leader){message('Escolha um Líder para continuar.',true);return;}step=next;document.querySelectorAll('[data-step]').forEach(b=>{b.classList.toggle('current',+b.dataset.step===step);b.setAttribute('aria-current',+b.dataset.step===step?'step':'false');});document.querySelectorAll('[data-step-panel]').forEach(p=>p.hidden=+p.dataset.stepPanel!==step);$('#builder-back').disabled=step===1;$('#builder-next').hidden=step===3;$('#builder-next').textContent=step===1?'Montar as 50 cartas →':'Revisar meu deck →';if(step===1)renderLeaders();if(step===2)renderPool();if(step===3)renderReview();}
  function renderLeaders(){const q=AtlasTaxonomy.canonical($('#leader-search').value);const color=$('#leader-color').value;const show=$('#leader-previews').checked;let choices=leaders.filter(c=>(!q||AtlasTaxonomy.canonical(c.name+' '+c.id).includes(q))&&(!color||c.color.split('/').includes(color))&&(show||!model.preview(c)));if(pending&&pending.type!=='DON'&&pending.type!=='LEADER')choices=choices.filter(l=>model.compatible(l,pending));$('#leader-count').textContent=choices.length+' Líderes nesta rota';$('#leader-more').hidden=choices.length<=leaderLimit;$('#leader-grid').innerHTML=choices.slice(0,leaderLimit).map(c=>`<button class="leader-choice ${deck.leader===c.uid?'selected':''}" data-select-leader="${esc(c.uid)}" aria-pressed="${deck.leader===c.uid}"><img src="${esc(image(c))}" alt="${esc(c.name)}" loading="lazy"><span>${esc(c.id)}${model.preview(c)?' · PRÉVIA':''}</span><b>${esc(c.name)}</b><small>${c.color.split('/').map(x=>Atlas.colors[x]?.[0]||x).join(' / ')} · ♡ ${esc(c.life)}</small></button>`).join('')||'<p class="empty-inline">Nenhum Líder corresponde à busca. Ajuste os filtros.</p>';$('#leader-selection').textContent=deck.leader?'Líder escolhido: '+lookup.get(deck.leader).name:pending?'Escolha um Líder com cores compatíveis com '+pending.name+'.':'Sua escolha define quais cores entram no deck.';}
  function renderPool(){const leader=lookup.get(deck.leader);const q=AtlasTaxonomy.canonical($('#deck-search').value),type=$('#deck-type').value,tag=$('#deck-topic').value;const rows=main.filter(c=>(!q||AtlasTaxonomy.canonical(c.name+' '+c.id+' '+c.archetype).includes(q))&&(!type||c.type===type)&&(!tag||AtlasTaxonomy.matches(c,[tag]))&&(!$('#compatible-only').checked||model.compatible(leader,c))&&($('#deck-previews').checked||!model.preview(c)));const pages=Math.max(1,Math.ceil(rows.length/12));page=Math.min(page,pages);$('#pool-summary').textContent=rows.length+' cartas · página '+page+' de '+pages;$('#pool-grid').innerHTML=rows.slice((page-1)*12,page*12).map(c=>{const qty=deck.cards[c.id]?.qty||0;const can=model.compatible(leader,c)&&qty<model.limit(c)&&model.total(deck)<50;return `<div class="builder-pool-card">${tile(c)}<button class="add-to-deck" data-add="${esc(c.uid)}" ${can?'':'disabled'}>${!model.compatible(leader,c)?'Cor incompatível':qty>=model.limit(c)?'Limite por ID atingido':model.total(deck)>=50?'Deck com 50 cartas':'+ Adicionar'} <span>${qty}/${model.limit(c)}</span></button></div>`;}).join('')||'<p class="empty-inline">Nenhuma carta nessa combinação de filtros.</p>';$('#pool-prev').disabled=page===1;$('#pool-next').disabled=page===pages;}
  function updatePanel(){const leader=lookup.get(deck.leader);$('#deck-name').value=deck.name;$('#deck-format').value=deck.format;const count=model.total(deck);$('#deck-counter').textContent=count+'/50';$('#mobile-deck-count').textContent=count+'/50';$('#deck-progress').style.width=Math.min(100,count*2)+'%';$('#deck-leader-preview').innerHTML=leader?`<img src="${esc(image(leader))}" alt="${esc(leader.name)}"><div><span>${esc(leader.id)}</span><b>${esc(leader.name)}</b><small>${leader.color.split('/').map(c=>Atlas.colors[c]?.[0]||c).join(' / ')}</small></div>`:'<span>⚑</span><p>Escolha seu Líder para começar.</p>';
    const rows=Object.entries(deck.cards).sort(([,a],[,b])=>(Number(lookup.get(a.uid)?.cost)||0)-(Number(lookup.get(b.uid)?.cost)||0));$('#deck-list').innerHTML=rows.map(([id,row])=>{const c=lookup.get(row.uid);return `<div class="deck-row ${model.compatible(leader,c)?'':'incompatible'}"><img src="${esc(image(c))}" alt="" loading="lazy"><a href="carta.html?id=${encodeURIComponent(c.uid)}"><b>${esc(c.name)}</b><small>${esc(id)} · ${esc(c.cost)} DON!!</small></a><div><button data-remove="${esc(id)}" aria-label="Remover uma cópia de ${esc(c.name)}">−</button><span>${row.qty}</span><button data-add="${esc(row.uid)}" aria-label="Adicionar uma cópia de ${esc(c.name)}" ${row.qty>=model.limit(c)||count>=50?'disabled':''}>+</button></div></div>`;}).join('')||'<div class="deck-empty"><span>♧</span><p>Sua tripulação ainda está se formando.<br>Adicione cartas pela biblioteca ao lado.</p></div>';
    $('#deck-don-label').textContent='10 DON!! · '+(lookup.get(deck.donArt)?.name||'arte livre');$('#builder-next').disabled=!leader;saveDraft();if(step===3)renderReview();}
  function renderReview(){const report=model.validate(deck,lookup),stats=model.analyze(deck,lookup);$('#review-state').textContent=report.ready?'Estrutura básica completa':'Sua tripulação precisa de ajustes';$('#review-state').classList.toggle('ready',report.ready);$('#review-findings').innerHTML=(report.errors.length?report.errors.map(text=>`<li class="finding-error">${esc(text)}</li>`):['<li class="finding-ok">50 cartas, Líder, dez DON!! e limites básicos conferidos.</li>']).join('')+report.notes.map(text=>`<li>${esc(text)}</li>`).join('');$('#deck-metrics').innerHTML=`<div><b>${stats.types.CHARACTER}</b><span>Personagens</span></div><div><b>${stats.types.EVENT}</b><span>Eventos</span></div><div><b>${stats.types.STAGE}</b><span>Cenários</span></div><div><b>${stats.counters}</b><span>Cartas com Counter</span></div>`;const max=Math.max(1,...stats.curve);$('#cost-curve').innerHTML=stats.curve.map((n,i)=>`<div><span>${n}</span><i style="height:${Math.max(3,n/max*100)}px"></i><small>${i===6?'6+':i}</small></div>`).join('');$('#cost-curve').setAttribute('aria-label','Curva de custo: '+stats.curve.map((n,i)=>`${i===6?'6 ou mais':i} DON!!: ${n} cartas`).join('; '));$('#sample-hand').disabled=model.total(deck)!==50;$('#mulligan-hand').disabled=!hand||hand.mulligan;const chosen=deck.donArt;$('#don-art').innerHTML='<option value="">Arte livre / DON!! padrão</option>'+dons.map(c=>`<option value="${esc(c.uid)}">${esc(c.name)}</option>`).join('');$('#don-art').value=chosen||'';$('#don-art').onchange=e=>{deck.donArt=e.target.value||null;updatePanel();};}
  function changed(){hand=null;$('#hand-preview').innerHTML='';$('#hand-caption').textContent='Use um deck com 50 cartas para experimentar uma mão de cinco.';updatePanel();if(step===1)renderLeaders();if(step===2)renderPool();}
  document.addEventListener('click',e=>{const leaderButton=e.target.closest('[data-select-leader]');if(leaderButton){deck.leader=leaderButton.dataset.selectLeader;if(pending&&pending.type!=='LEADER'&&pending.type!=='DON'){const error=model.add(deck,pending,lookup);if(!error){message(pending.name+' foi adicionada ao rascunho.');pending=null;}else message(error,true);}changed();return;}const add=e.target.closest('[data-add]');if(add){const c=lookup.get(add.dataset.add);const error=model.add(deck,c,lookup);if(error)message(error,true);else{message(c.name+' adicionada ao deck.');changed();}return;}const remove=e.target.closest('[data-remove]');if(remove){const row=deck.cards[remove.dataset.remove];if(row){row.qty--;if(!row.qty)delete deck.cards[remove.dataset.remove];changed();}}});
  document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>setStep(+b.dataset.step));$('#builder-back').onclick=()=>setStep(Math.max(1,step-1));$('#builder-next').onclick=()=>setStep(Math.min(3,step+1));
  $('#leader-more').onclick=()=>{leaderLimit+=48;renderLeaders();};['leader-search','leader-color','leader-previews'].forEach(id=>$('#'+id).oninput=()=>{leaderLimit=48;renderLeaders();});['deck-search','deck-type','deck-topic','compatible-only','deck-previews'].forEach(id=>$('#'+id).oninput=()=>{page=1;renderPool();});$('#pool-prev').onclick=()=>{page--;renderPool();};$('#pool-next').onclick=()=>{page++;renderPool();};$('#deck-topic').innerHTML='<option value="">Todos os grupos</option>'+AtlasTaxonomy.topics.map(t=>`<option value="${t.id}">${esc(t.label)}</option>`).join('');
  $('#deck-name').oninput=e=>{deck.name=e.target.value.slice(0,80);saveDraft();};$('#deck-format').onchange=e=>{deck.format=e.target.value;changed();};$('#new-deck').onclick=()=>{deck=blank();savedId=null;pending=null;changed();setStep(1);message('Novo rascunho iniciado. Os decks salvos continuam disponíveis.');};
  $('#save-deck').onclick=()=>{if(!deck.leader){message('Escolha um Líder antes de salvar.',true);return;}deck.name=deck.name.trim()||'Minha tripulação';const list=savedList();savedId=savedId||('deck-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,7));const entry={id:savedId,data:model.exported(deck),updatedAt:new Date().toISOString()};const index=list.findIndex(d=>d.id===savedId);if(index>=0)list[index]=entry;else list.push(entry);if(!write('atlas-saved-decks',list)){message('Não foi possível salvar neste navegador.',true);return;}fillSaved();updatePanel();message('Deck salvo neste navegador. Exporte um arquivo para guardar uma cópia.');};
  $('#load-deck').onclick=()=>{const row=savedList().find(d=>d.id===$('#saved-decks').value);if(!row){message('Escolha um deck salvo.',true);return;}try{deck=model.parseImport(row.data,lookup);savedId=row.id;changed();setStep(2);message('Deck carregado.');}catch(e){message(e.message,true);}};
  function download(content,extension,type){const name=(AtlasTaxonomy.canonical(deck.name)||'deck-atlas').replace(/\s+/g,'-');const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name+'.'+extension;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  $('#export-json').onclick=()=>{if(!deck.leader)return message('Escolha um Líder antes de exportar.',true);download(JSON.stringify(model.exported(deck),null,2),'json','application/json');};$('#export-text').onclick=()=>{if(!deck.leader)return message('Escolha um Líder antes de exportar.',true);const leader=lookup.get(deck.leader);const lines=['# '+deck.name,'# Líder','1x '+leader.id+' '+leader.name,'','# Deck principal',...Object.entries(deck.cards).map(([id,row])=>row.qty+'x '+id+' '+lookup.get(row.uid).name),'','# DON!!','10x '+(lookup.get(deck.donArt)?.name||'DON!!'),'','# Estrutura básica; conferir formato e lista vigente.'];download(lines.join('\n'),'txt','text/plain;charset=utf-8');};
  const importer=$('#deck-import');$('#import-deck').onclick=()=>importer.click();importer.onchange=async()=>{const file=importer.files?.[0];if(!file)return;try{if(file.size>200000)throw Error('Use um JSON de até 200 KB.');const imported=model.parseImport(await file.text(),lookup);deck=imported;savedId=null;pending=null;changed();setStep(2);message('Deck importado; confira a revisão antes de usar.');}catch(e){message(e.message,true);}finally{importer.value='';}};
  function sample(mulligan=false){const pool=[];for(const row of Object.values(deck.cards))for(let i=0;i<row.qty;i++)pool.push(lookup.get(row.uid));if(pool.length!==50)return;if(mulligan&&(!hand||hand.mulligan))return;for(let i=pool.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[pool[i],pool[j]]=[pool[j],pool[i]];}hand={cards:pool.slice(0,5),mulligan};$('#hand-preview').innerHTML=hand.cards.map(c=>`<a href="carta.html?id=${encodeURIComponent(c.uid)}"><img src="${esc(image(c))}" alt="${esc(c.name)}"><span>${esc(c.name)}</span></a>`).join('');$('#hand-caption').textContent=mulligan?'Mulligan usado: a mão inteira foi devolvida, o conjunto reembaralhado e cinco cartas foram compradas.':'Mão ilustrativa de cinco cartas, sem alterar seu deck salvo. Você pode trocar a mão inteira uma vez.';$('#mulligan-hand').disabled=mulligan;}
  $('#sample-hand').onclick=()=>sample();$('#mulligan-hand').onclick=()=>sample(true);
  fillSaved();changed();setStep(step);
})();
